/**
 * Small read-only label for status or category (`design/components/badge.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/badge.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { mergeProps, type JSX } from 'solid-js'

import {
  Icon,
  claimSlot,
  createDerived,
  resolveSlot,
  scope,
  type Defaults,
  type IconRole,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/structure/badge.module.css'

export type BadgeTone = NonNullable<BadgeProps['tone']>

export type BadgeVariant = NonNullable<BadgeProps['variant']>

export interface BadgeProps {
  /**
   * Short text, about two words at most. A dot does not draw it and keeps it for assistive
   * technology. Required unless `count` is given.
   */
  children?: JSX.Element
  /**
   * A number drawn in the text's place. Past `max` it reads as `max` and a plus sign. Zero or
   * less draws nothing.
   */
  count?: number
  /**
   * A mark with no number, for "something is new". `children` names it to a screen reader;
   * without `children` it is hidden from assistive technology.
   */
  dot?: boolean
  /**
   * Leading and decorative; the text carries the meaning. Not drawn by a count or a dot.
   */
  icon?: IconRole
  /**
   * The largest count drawn as it is; default 99.
   */
  max?: number
  tone?: 'info' | 'warning' | 'success' | 'accent' | 'danger' | 'neutral'
  variant?: 'solid' | 'soft' | 'outline'
}

/** Small read-only label for status or category. */
export default function Badge(given: BadgeProps): JSX.Element {
  const props = mergeProps(
    { variant: 'soft', tone: 'neutral', max: 99, dot: false } as Defaults<
      BadgeProps,
      'variant' | 'tone' | 'max' | 'dot'
    >,
    claimSlot(given),
  )
  return scope(() => {
    const childrenSlot = resolveSlot(() => props.children)
    const shown = createDerived(() =>
      props.count === undefined
        ? ''
        : props.count > props.max
          ? String(props.max) + '+'
          : String(props.count),
    )
    return (
      <>
        {props.count !== undefined ? (
          props.count > 0 ? (
            <span
              class={styles.badge}
              data-variant={props.variant}
              data-tone={props.tone}
              data-count={''}
              data-member="badge"
            >
              {shown.value}
            </span>
          ) : null
        ) : props.dot ? (
          <span
            class={styles.badge}
            data-variant={props.variant}
            data-tone={props.tone}
            aria-hidden={childrenSlot.text() === '' ? true : undefined}
            data-dot={''}
            data-member="badge"
          >
            {childrenSlot.text() !== '' ? (
              <span class={styles.spoken}>{childrenSlot()}</span>
            ) : null}
          </span>
        ) : (
          <span
            class={styles.badge}
            data-variant={props.variant}
            data-tone={props.tone}
            data-member="badge"
          >
            {props.icon !== undefined ? (
              <span class={styles.glyph}>
                <Icon name={props.icon} size="sm" />
              </span>
            ) : null}
            {childrenSlot()}
          </span>
        )}
      </>
    )
  })
}
